{
  "probability": 0.01,
  "range_low": 0.01,
  "range_high": 0.03,
  "summary": [
    "Bayesian posterior assigns 1% probability to AfD winning the most seats in BW, reflecting a strong base-rate against AfD historically leading BW.",
    "Current polls show CDU and Greens ahead or very close, with AfD around 19–21%, not exceeding the top two parties.",
    "Isolated polling anomalies where AfD edges Greens exist but have not produced a credible path to a first-place seat lead.",
    "Late-stage dynamics or surges would be required to overturn the baseline, but are not evidenced robustly in the available forecasts."
  ],
  "confidence": "low",
  "narrative": "Starting from a low base-rate anchor, substantial polling evidence against AfD leading BW—coupled with a strong historical precedent—drives the calibrated posterior to about 1%. While tail risks exist from isolated polls, they do not meaningfully alter the overall low probability."
  ,
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "reference class indicates a long-run base-rate near 5% for AfD to be the single largest party in BW, given multi-party competition and historical outcomes."
    },
    "factor_updates": [
      {
        "factor": "CDU polling lead and Greens near ahead",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Polls consistently place CDU ~27–29% and Greens ~21–23% with AfD ~19–21%, making AfD unlikely to be the largest party."
      },
      {
        "factor": "Greens near parity or ahead in some polls",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greens’ strength near AfD reduces the chance that AfD surpasses both major rivals to lead the Landtag."
      },
      {
        "factor": "Historical baseline: AfD has never led BW",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Prior results anchor the probability away from AfD leading, reinforcing a low posterior."
      },
      {
        "factor": "Lack of credible late surge evidence",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "No robust late-stage dynamics indicating a shift that would place AfD first."
      },
      {
        "factor": "Isolated polls showing AfD ahead of Greens",
        "direction": "up",
        "magnitude": "low",
        "rationale": "Tail-risk signals exist but are not persistent or strong enough to materially move the posterior."
      }
    ],
    "synthesis_rationale": "Calibrated across a strong downward bias from the anchor due to consistent polling standings and historical precedent, with modest upside from isolated polls treated as low-probability tail risk. Correlations across polls and the multi-party structure justify a narrow posterior around 1% with a plausible 1–3% range."
  }
}

{
  "probability": 0.01,
  "range_low": 0.01,
  "range_high": 0.04,
  "summary": [
    "Current Baden-Württemberg polls place CDU as the leading party with Greens close behind and AfD around 19–21%, making AfD the most likely to lead very unlikely.",
    "Historical baseline shows AfD has never led the BW Landtag; Greens or CDU have consistently held the top seat share.",
    "Bayesian-calibrated posterior probability for AfD winning the most seats is about 1% (range roughly 1–4%), reflecting strong downward updates from multiple factors."
  ],
  "confidence": "high",
  "narrative": "Starting from a modest anchor in the reference class, consistent CDU leads and historical precedence drive the probability of AfD leading BW down substantially. Even with near-20% support in polls, the combination of a CDU lead, Greens near parity, and a strong historical baseline yields a very low posterior around 1% with a plausible 0–4% uncertainty window.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "reference class is Baden-Württemberg Landtag elections where CDU or Greens typically win the most seats; anchor probability of 5% reflects a plausible baseline before updates, given that AfD has not led BW in recent elections."
    },
    "factor_updates": [
      {
        "factor": "CDU polling lead over AfD",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Polls consistently place CDU around 27–29% while AfD sits near 19–21%, which strongly reduces the chance AfD is the largest party."
      },
      {
        "factor": "Greens' vote share near AfD in several polls",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greens polling in the low- to mid-20s keeps AfD from surpassing both major rivals to lead the Landtag."
      },
      {
        "factor": "Occasional AfD lead over Greens in BWTrend",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "BWTrend has shown AfD ahead of Greens in some instances, signaling non-negligible upside risk but not a durable lead."
      },
      {
        "factor": "Strong historical baseline: AfD has never led BW Landtag",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Historical results impose a base-rate that disfavors AfD leading in seats."
      },
      {
        "factor": "Multi-party competition dampens single-party dominance",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "With CDU and Greens competing closely and AfD not consistently ahead, securing the most seats remains unlikely."
      }
    ],
    "synthesis_rationale": "The updates collectively imply a downshift from the anchor due to a combination of a stable CDU lead, Greens near parity that constrains AfD, and the long-standing baseline that AfD has not led BW. An occasional uptick in BWTrend polls introduces upside risk but is insufficient to overcome the established multi-party dynamics. The result is a calibrated, tightly down-weighted posterior near 1%, with a conservative uncertainty band."
  }
}

{
  "probability": 0.08,
  "range_low": 0.04,
  "range_high": 0.14,
  "summary": [
    "Base-rate historical evidence implies AfD has not led the Baden-Württemberg Landtag; the anchor probability for AfD being the largest party is very low (roughly 0–5%).",
    "Current polls around Feb 2026 place CDU ahead or near the top, with AfD around 19–21% and Greens around 20–23%, making a CDU-led or Greens-led majority likely and AfD unlikely to lead in seats.",
    "Contrarian signals exist: BWTrend has shown AfD ahead of Greens in some polls, suggesting a non-negligible upside risk if that pattern persists; turnout dynamics could also tip marginally in AfD’s favor.",
    "Greens leadership stability and multi-party dynamics further dampen AfD’s chances, but late shifts could modestly raise the probability above the anchor; overall estimate remains small but non-zero."
  ],
  "confidence": "high",
  "narrative": "Although historical baselines and current polls strongly favor CDU or Greens over AfD, occasional poll anomalies and turnout dynamics create a non-trivial upside risk. The synthesized, calibrated view places AfD at about 8% chance of winning the most seats, with a plausible 4–14% uncertainty range given potential late shifts.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "reference class consists of Baden-Württemberg Landtag elections where AfD has never led as the largest party; Greens or CDU have historically led, establishing a strong base-rate that AfD winning the most seats is unlikely."
    },
    "factor_updates": [
      {
        "factor": "CDU polling lead over AfD",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Polls consistently place CDU around 27–29% while AfD sits near 19–21%, reinforcing the baseline that AfD would need a substantial, unlikely swing to exceed CDU."
      },
      {
        "factor": "Greens' vote share near AfD in several polls",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greens polling in the low to mid-20s keeps AfD from surpassing both major rivals to lead the Landtag."
      },
      {
        "factor": "Occasional AfD lead over Greens in BWTrend",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "BWTrend has shown AfD ahead of Greens in some instances, signaling upside risk if that dynamic persists."
      },
      {
        "factor": "Strong historical baseline: AfD has never led BW Landtag",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Historical results anchor a low base-rate for AfD leading, constraining upside scenarios."
      },
      {
        "factor": "Turnout and late swing dynamics",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Late shifts in turnout or support could marginally lift AfD, though would still need to overcome CDU/Greens leads."
      }
    ],
    "synthesis_rationale": "Starting from a conservative anchor of 5%, the contrarian updates tilt the probability modestly upward due to occasional polls where AfD edges Greens and due to turnout/late-swing risks. However, the dominant signals—CDU lead and strong historical baseline—keep the final estimate tightly bounded around the anchor, resulting in a calibrated probability of 8% with a plausible 4–14% range. Calibration acknowledges both upside risk and substantial structural constraints."
  }
}
